import { test, expect, type Page } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, inviteAndJoin } from './helpers';

// [Verifier] NOTE: the snake's food cell is placed via Math.random(), so a
// real score/length change can't be produced deterministically through pure
// key input alone. We pin Math.random() from inside the already-loaded page
// (never touching app source) so the next food spawn lands at a known grid
// cell, then drive the snake there with arrow keys. This exercises the real
// update_status -> sidebar path end to end instead of a no-op status ping.
async function pinNextFoodSpawns(page: Page, randomValues: number[]) {
  await page.evaluate((values) => {
    let i = 0;
    const orig = Math.random.bind(Math);
    Math.random = () => (i < values.length ? values[i++] : orig());
  }, randomValues);
}

async function waitForHeadAt(page: Page, targetIdx: number) {
  await page.waitForFunction(
    (target) => {
      const cells = document.querySelectorAll('[data-testid="snake-grid"] i');
      for (let idx = 0; idx < cells.length; idx++) {
        if (cells[idx].classList.contains('head')) return idx === target;
      }
      return false;
    },
    targetIdx,
    { timeout: 5_000 },
  );
}

/** Starts a fresh game and eats exactly one food pinned at grid cell (0,0),
 *  growing score by 10 and length by 1; the snake then runs into the wall on
 *  its own right after, ending the game. */
async function playOneFoodThenEnd(page: Page) {
  await pinNextFoodSpawns(page, [0, 0.999]);
  await page.getByTestId('start-game-btn').click();
  await page.keyboard.press('ArrowUp');
  await waitForHeadAt(page, 7); // reached row 0, still column 7
  await page.keyboard.press('ArrowLeft');
  await waitForHeadAt(page, 0); // reached (0,0) -- eats the pinned food
}

test.describe(`player: see everyone in the room with their live status, score, and snake length while I play`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`when a player's score or length changes, every other room member sees the update in the sidebar within a few seconds`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await inviteAndJoin(pageA, pageB);

    await playOneFoodThenEnd(pageA);

    // B's sidebar (self excluded) shows A's row updated to score 10 / len 4.
    const aRow = pageB
      .getByTestId('item-player_status')
      .filter({ hasText: 'score 10' })
      .filter({ hasText: 'len 4' });
    await expect(aRow).toBeVisible({ timeout: 5_000 });

    await ctxA.close();
    await ctxB.close();
  });

  test(`a player's status shows as playing while their game is active and idle otherwise`, async ({ page }) => {
    await createWorkspace(page);
    // [Verifier] NOTE: no testid on the HUD status value; falling back to the
    // status class the component already applies (`b.playing` / `b.idle`).
    await expect(page.locator('b.idle')).toBeVisible();

    await page.getByTestId('start-game-btn').click();
    await expect(page.locator('b.playing')).toBeVisible({ timeout: 3_000 });

    // Drive the snake straight into the wall to end the game deterministically.
    await page.keyboard.press('ArrowUp');
    await expect(page.locator('b.idle')).toBeVisible({ timeout: 5_000 });
  });
});
